// Seeded random draws for bench generation.
// It takes a numeric seed and emits a deterministic draw stream.
// Every generated byte derives from this stream, so a plan always regenerates the same repo.
// Templates never touch Math.random: replay the seed, replay the bytes.
// Zipf tables turn uniform draws into power-law ranks, so small pools collide like real code.

export type Rng = () => number

export function mulberry32(seed: number): Rng {
  let state = seed >>> 0
  return (): number => {
    state = (state + 0x6d2b79f5) >>> 0
    let mixed = Math.imul(state ^ (state >>> 15), 1 | state)
    mixed = (mixed + Math.imul(mixed ^ (mixed >>> 7), 61 | mixed)) ^ mixed
    return ((mixed ^ (mixed >>> 14)) >>> 0) / 4294967296
  }
}

export function int(rng: Rng, min: number, max: number): number {
  return min + Math.floor(rng() * (max - min + 1))
}

export function pick<T>(rng: Rng, items: readonly T[]): T {
  return items[Math.floor(rng() * items.length)] as T
}

export interface ZipfTable {
  size: number
  cutoffs: number[]
}

export function zipfTable(size: number, skew: number): ZipfTable {
  const weights: number[] = []
  let total = 0
  for (let rank = 0; rank < size; rank += 1) {
    total += 1 / (rank + 1) ** skew
    weights.push(total)
  }
  return { size, cutoffs: weights.map((weight) => weight / total) }
}

export function zipfDraw(rng: Rng, table: ZipfTable): number {
  const roll = rng()
  let low = 0
  let high = table.size - 1
  while (low < high) {
    const mid = (low + high) >> 1
    if (roll < (table.cutoffs[mid] as number)) high = mid
    else low = mid + 1
  }
  return low
}
